/* words that carry no meaning when searching */
const G_STOP=new Set(['for','the','a','an','what','to','use','can','i','me','my','make','making','is','are','best','which','of','in','and','or','customer','wants','want','need','looking','something','steel','metal','material','should','we','give','with','it','be','how','do','does','कि','के','का','की','में','से','और','क्या','लिए','ke','ka','ki','mein','se','aur','kya','liye','hai','ho','chahiye','banana','banane','चाहिए','बनाना','बनाने','है']);
function guideSearch(q){
  const toks=String(q||'').toLowerCase().split(/[^\p{L}\p{N}ऀ-ॿ]+/u).filter(x=>x&&x.length>=2&&!G_STOP.has(x));
  if(!toks.length)return {toks,hits:[],grades:[]};
  const hits=GUIDE.map(e=>{
    const nm=e.name.join(' ').toLowerCase();let s=0;
    toks.forEach(tk=>{if(nm.includes(tk))s+=3;if(e.kw.split(/\s+/).some(w=>w===tk))s+=3;else if(tk.length>=3&&e.kw.includes(tk))s+=1;
      if(e.pick.some(p=>p[0].toLowerCase()===tk))s+=1});
    return {e,s};
  }).filter(x=>x.s>0).sort((a,b)=>b.s-a.s).map(x=>x.e);
  const grades=db.mats.filter(m=>toks.some(tk=>m.id.toLowerCase()===tk||(tk.length>=3&&m.id.toLowerCase().startsWith(tk))));
  return {toks,hits,grades};
}
